files.content:
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1e1e2f;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: #e0e0e0;
  padding: 16px;
}

.card {
  background: #2a2a40;
  border-radius: 16px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  color: #f0f0f0;
  letter-spacing: 1px;
}

.inputs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 8px 12px;
  margin-bottom: 24px;
}

.inputs label {
  font-size: 1rem;
  color: #b0b0c0;
}

.inputs input {
  width: 80px;
  padding: 8px 12px;
  font-size: 1.125rem;
  border: 2px solid #4a4a6a;
  border-radius: 8px;
  background: #1e1e2f;
  color: #e0e0e0;
  text-align: center;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.inputs input:focus {
  outline: none;
  border-color: #6c63ff;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

.display {
  font-size: 4.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 4px;
  color: #ffffff;
  margin: 16px 0;
  line-height: 1.2;
  text-shadow: 0 0 20px rgba(108, 99, 255, 0.5);
}

.message {
  min-height: 2rem;
  font-size: 1.25rem;
  font-weight: 600;
  color: #ff6b6b;
  margin-bottom: 16px;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
}

button {
  padding: 12px 24px;
  font-size: 1.125rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  background: #4a4a6a;
  color: #e0e0e0;
  min-width: 100px;
}

button:hover {
  background: #5a5a7a;
}

button:focus-visible {
  outline: 3px solid #6c63ff;
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
}

#start {
  background: #6c63ff;
  color: #fff;
}

#start:hover {
  background: #7b73ff;
}

#pause {
  background: #ffa94d;
  color: #1e1e2f;
}

#pause:hover {
  background: #ffb86b;
}

#reset {
  background: #ff6b6b;
  color: #fff;
}

#reset:hover {
  background: #ff8585;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

@media (max-width: 400px) {
  .display {
    font-size: 3.5rem;
  }
  button {
    min-width: 80px;
    padding: 10px 16px;
    font-size: 1rem;
  }
}

'use strict';

const minutesInput = document.getElementById('minutes');
const secondsInput = document.getElementById('seconds');
const display = document.getElementById('display');
const message = document.getElementById('message');
const startBtn = document.getElementById('start');
const pauseBtn = document.getElementById('pause');
const resetBtn = document.getElementById('reset');

let timer = null;
let remaining = 0;
let running = false;

function formatTime(sec) {
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function updateDisplay() {
  display.textContent = formatTime(remaining);
}

function stopTimer() {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
  running = false;
}

function tick() {
  remaining--;
  if (remaining <= 0) {
    remaining = 0;
    updateDisplay();
    stopTimer();
    message.textContent = "Time's up!";
  } else {
    updateDisplay();
  }
}

function start() {
  if (running) return;
  if (remaining <= 0) {
    const m = Math.max(0, Math.min(99, parseInt(minutesInput.value, 10) || 0));
    const s = Math.max(0, Math.min(59, parseInt(secondsInput.value, 10) || 0));
    remaining = m * 60 + s;
  }
  if (remaining <= 0) return;
  message.textContent = '';
  updateDisplay();
  running = true;
  timer = setInterval(tick, 1000);
}

function pause() {
  if (!running) return;
  stopTimer();
}

function reset() {
  stopTimer();
  remaining = 0;
  message.textContent = '';
  updateDisplay();
}

startBtn.addEventListener('click', start);
pauseBtn.addEventListener('click', pause);
resetBtn.addEventListener('click', reset);

updateDisplay();
